@RestController
@RequestMapping("/api/users")
public class UserController {

    // 1. URI Path Versioning
    @GetMapping("/v1/{id}")
    public ResponseEntity<UserV1Response> getUserV1(@PathVariable Long id) {
        return ResponseEntity.ok(new UserV1Response(id, "John Doe"));
    }

    // 2. Content Negotiation (Media Type) Versioning
    @GetMapping(value = "/{id}", produces = "application/vnd.company.v2+json")
    public ResponseEntity<UserV2Response> getUserV2(@PathVariable Long id) {
        return ResponseEntity.ok(new UserV2Response(id, "John", "Doe"));
    }
}
